SELECT block_number, block_hash, block_timestamp, beneficiary_address, transaction_count, gas_used
FROM `nl2sparql-thesis.nl2sparql_analytics.block_facts`(DATE '{start_date}', DATE '{end_date}')
WHERE block_number = {block_number}

SELECT transaction_hash, block_timestamp, receipt_gas_used, gas_price_wei
FROM `nl2sparql-thesis.nl2sparql_analytics.transaction_facts`(DATE '{start_date}', DATE '{end_date}')
WHERE is_success IS FALSE AND receipt_gas_used >= {gas_used}
ORDER BY receipt_gas_used DESC
LIMIT {n}
